// Holding registers 0..11 from the ChinarSoft virtual machine -> one object
const r = msg.payload;
const STATES  = ['STOPPED', 'RUNNING', 'IDLE', 'FAULT', 'CHANGEOVER', 'PLANNED_STOP'];
const REASONS = ['-', 'material shortage', 'jam', 'motor overload', 'sensor fault',
                 'changeover', 'break/meal', 'planned maintenance'];

msg.payload = {
    state:      STATES[r[0]] ?? `UNKNOWN(${r[0]})`,
    reason:     REASONS[r[1]] ?? String(r[1]),
    good:       r[2] * 65536 + r[3],      // 32-bit counter, high word first
    scrap:      r[4] * 65536 + r[5],
    idealCycle: r[6] / 10,                // seconds
    cycle:      r[7] / 10,                // seconds
    product:    r[8],
    temp:       r[9] / 10,                // degC
    heartbeat:  r[10],                    // +1 per machine second
    inState:    r[11]                     // machine seconds in current state
};
return msg;

// Detects every state change and turns each finished stop into one record.
// Time comes from the machine's own heartbeat (+1 per machine second),
// so durations stay correct at any simulator --speed.
const p = msg.payload;
const PLANNED = ['CHANGEOVER', 'PLANNED_STOP'];
const bucket = s => s === 'RUNNING' ? 'run' : PLANNED.includes(s) ? 'planned' : 'unplanned';

let last   = context.get('last');
let clock  = context.get('clock')  || 0;                    // machine seconds
let totals = context.get('totals') || { run: 0, planned: 0, unplanned: 0 };
let log    = context.get('log')    || [];

const add = {};                                             // machine seconds per bucket in this reading
const credit = (b, sec) => { totals[b] += sec; add[b] = (add[b] || 0) + sec; };
if (!last) {                                                // first reading
    const r = flow.get('restore');                          // what InfluxDB already knew
    if (r === undefined) return null;                       // wait until the restore query answered
    clock = p.heartbeat;
    last  = { state: p.state, reason: p.reason, since: clock - p.inState };
    if (r && r.heartbeat !== undefined) {                   // Node-RED restarted mid-shift
        totals = { ...totals, ...r.totals };
        log    = r.log;
        const gap  = (p.heartbeat - r.heartbeat + 65536) % 65536;   // machine seconds we missed
        const here = Math.min(gap, p.inState);              // current state: the machine tells us
        credit(bucket(p.state), here);
        // the rest of the gap: the part counter tells us how much of it was running
        let parts = (p.good + p.scrap) - r.parts;
        if (p.state === 'RUNNING') parts -= here / p.cycle;
        const rest = gap - here;
        const run  = Math.min(rest, Math.max(0, parts) * r.cycle);
        if (run > 0) credit('run', Math.round(run));
        const left = rest - Math.round(run);                // stopped, but we didn't see why
        if (left > 0) credit(r.bucket === 'run' ? 'unplanned' : r.bucket, left);
    } else {                                                // fresh start
        credit(bucket(p.state), p.inState);
    }
} else {
    const dt = (p.heartbeat - last.hb + 65536) % 65536;     // heartbeat wraps at 65535
    clock += dt;
    credit(bucket(last.state), dt);
}

const hhmm = s => String(Math.floor(s / 3600)).padStart(2, '0') + ':' +
                  String(Math.floor(s / 60) % 60).padStart(2, '0');
let stop = null;

if (p.state !== last.state) {
    if (last.state !== 'RUNNING') {                          // a stop just ended
        stop = { payload: {
            start:   hhmm(last.since),
            end:     hhmm(clock),
            minutes: Math.round((clock - last.since) / 6) / 10,
            state:   last.state,
            reason:  last.reason,
            type:    bucket(last.state),
            ts:      Date.now(),                         // InfluxDB timestamp of this stop
            sinceS:  last.since                          // machine second the stop began
        }};
        log = [stop.payload, ...log].slice(0, 50);           // newest first
    }
    last = { state: p.state, reason: p.reason, since: clock };
}
last.hb = p.heartbeat;

context.set('last', last);
context.set('clock', clock);
context.set('totals', totals);
context.set('log', log);

const live = { payload: { ...p, clock: hhmm(clock), clockS: clock, since: last.since,
    bucket: bucket(p.state), add, totals: {
    run:       Math.round(totals.run / 60),
    planned:   Math.round(totals.planned / 60),
    unplanned: Math.round(totals.unplanned / 60)
}}};
return [live, stop, stop ? { payload: log } : null];

// One CSV line per stop; writes the header once when the file is new.
const s = msg.payload;
const file = env.get('STOPS_FILE') || 'stops.csv';
let line = [s.start, s.end, s.minutes, s.state, s.reason, s.type].join(',');
if (!fs.existsSync(file)) line = 'start,end,minutes,state,reason,type\n' + line;
msg.filename = file;
msg.payload = line;
return msg;

// Every reading -> InfluxDB line protocol:  measurement,tags fields timestamp
// dt = machine seconds since the last reading, tagged with the bucket they belong to
const p = msg.payload;
const ts = Date.now();
const lines = Object.entries(p.add).map(([bucket, dt]) =>
    `machine,line=packaging,bucket=${bucket} ` +
    `state="${p.state}",reason="${p.reason}",good=${p.good}i,scrap=${p.scrap}i,` +
    `cycle=${p.cycle},temp=${p.temp},dt=${dt}i,heartbeat=${p.heartbeat}i ${ts}`);
if (!lines.length) return null;
msg.payload = lines.join('\n');
return msg;

// Every finished stop -> one line in the 'stops' table
// op_reason starts empty; the operator tablet fills it in later (same row)
const s = msg.payload;
const esc = t => String(t).replace(/[ ,=]/g, m => '\\' + m);
msg.payload =
    `stops,line=packaging,type=${s.type},state=${s.state},reason=${esc(s.reason)} ` +
    `minutes=${s.minutes},started="${s.start}",ended="${s.end}",op_reason="" ` +
    s.ts;
return msg;

// POST line protocol to InfluxDB 3 Core
msg.method  = 'POST';
msg.url     = `${env.get('INFLUX_URL') || 'http://127.0.0.1:8181'}/api/v3/write_lp?db=factory&precision=ms`;
msg.headers = { 'Authorization': 'Bearer ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'text/plain' };
return msg;

// On start: ask InfluxDB what it already knows about this shift (last 8 hours)
const base = env.get('INFLUX_URL') || 'http://127.0.0.1:8181';
const headers = { 'Authorization': 'Bearer ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'application/json' };
const q = sql => ({ method: 'POST', url: `${base}/api/v3/query_sql`, headers,
                    payload: { db: 'factory', q: sql, format: 'json' } });
flow.set('restore', undefined);
return [
  { ...q(`SELECT bucket, SUM(dt) AS seconds FROM machine
           WHERE time > now() - INTERVAL '8 hours' GROUP BY bucket`), topic: 'totals' },
  { ...q(`SELECT bucket, heartbeat, good, scrap, cycle FROM machine
           WHERE time > now() - INTERVAL '8 hours' ORDER BY time DESC LIMIT 1`), topic: 'last' },
  { ...q(`SELECT started, ended, minutes, state, reason, type FROM stops
           WHERE time > now() - INTERVAL '8 hours' ORDER BY time DESC LIMIT 50`), topic: 'log' },
  { ...q(`SELECT time, started, ended, minutes, state, reason, type FROM stops
           WHERE state = 'IDLE' AND op_reason = '' AND time > now() - INTERVAL '8 hours'
           ORDER BY time DESC`), topic: 'pending' },
  { ...q(`SELECT MIN(time) AS t FROM machine WHERE time > now() - INTERVAL '8 hours'`), topic: 'first' }
];

// Collect the three answers, then hand them to 'Detect stops'
const got = context.get('got') || {};
const ok  = msg.statusCode === 200 && Array.isArray(msg.payload);
got[msg.topic] = ok ? msg.payload : [];
if (!ok) node.warn(`InfluxDB ${msg.topic}: ${msg.statusCode} – starting from zero`);
if (Object.keys(got).length < 5) { context.set('got', got); return null; }
context.set('got', {});
// the report covers everything since this shift's first reading
const first = got.first[0] && got.first[0].t;
flow.set('shiftStart', first ? Date.parse(first + 'Z') : Date.now());
flow.set('reported', false);
// idle stops nobody has explained yet -> back on the operator tablet
const pending = got.pending.map(p => ({ ts: Date.parse(p.time + 'Z'), start: p.started, end: p.ended,
    minutes: p.minutes, state: p.state, reason: p.reason, type: p.type }));
flow.set('pending', pending);
const toTablet = { payload: pending };

if (!got.last.length) {                                   // nothing stored yet
    flow.set('restore', false);           // false = nothing to restore (null would delete the key)
    node.status({ fill: 'grey', shape: 'dot', text: 'fresh start' });
    return [null, toTablet];
}
const totals = { run: 0, planned: 0, unplanned: 0 };
got.totals.forEach(r => totals[r.bucket] = Number(r.seconds));
const log = got.log.map(r => ({ start: r.started, end: r.ended, minutes: r.minutes,
                                state: r.state, reason: r.reason, type: r.type }));
const L = got.last[0];
flow.set('restore', { totals, log, heartbeat: Number(L.heartbeat), bucket: L.bucket,
                      parts: Number(L.good) + Number(L.scrap), cycle: Number(L.cycle) || 2 });
node.status({ fill: 'green', shape: 'dot',
              text: `restored ${Math.round((totals.run + totals.planned + totals.unplanned) / 60)} min, ${log.length} stops` });
return [{ payload: log }, toTablet];

// The machine knows THAT it was idle (infeed empty), not WHY.
// Every finished idle stop goes onto the operator tablet.
const s = msg.payload;
if (s.state !== 'IDLE') return null;
const pending = flow.get('pending') || [];
pending.unshift({ ts: s.ts, start: s.start, end: s.end, minutes: s.minutes,
                  state: s.state, reason: s.reason, type: s.type });
flow.set('pending', pending);
return { payload: pending };

// The operator tapped a reason. Write it to the SAME row in InfluxDB:
// same table, same tags, same timestamp -> InfluxDB adds the new fields to that stop.
const { ts, reason } = msg.payload;
let pending = flow.get('pending') || [];
const s = pending.find(p => p.ts === ts);
if (!s) return null;                                   // already answered (two tablets?)
pending = pending.filter(p => p.ts !== ts);
flow.set('pending', pending);
const esc = t => String(t).replace(/[ ,=]/g, m => '\\' + m);
const line =
    `stops,line=packaging,type=${s.type},state=${s.state},reason=${esc(s.reason)} ` +
    `op_reason="${reason.replace(/"/g, '')}",operator="tablet" ${s.ts}`;
node.status({ fill: 'green', shape: 'dot', text: `${s.start} → ${reason}` });
return [{ payload: line }, { payload: pending }];

// An unplanned stop has been running for ALERT_MIN machine minutes -> raise ONE alert for it.
const p = msg.payload;
const LIMIT = (Number(env.get('ALERT_MIN')) || 5) * 60;            // machine seconds
if (p.bucket !== 'unplanned') return null;
const dur = p.clockS - p.since;
const open = flow.get('alert');
if (dur < LIMIT || (open && open.since === p.since)) return null;   // too short, or already alerted
const esc = t => String(t).replace(/[ ,=]/g, m => '\\' + m);
const hhmm = s => String(Math.floor(s / 3600)).padStart(2, '0') + ':' +
                  String(Math.floor(s / 60) % 60).padStart(2, '0');
const a = { since: p.since, ts: Date.now(), state: p.state, reason: p.reason,
            start: hhmm(p.since), at: hhmm(p.clockS), minutes: Math.round(dur / 6) / 10, status: 'open' };
flow.set('alert', a);
const list = [a, ...(flow.get('alerts') || [])].slice(0, 10);
flow.set('alerts', list);
const line = `alerts,line=packaging,state=${a.state},reason=${esc(a.reason)} ` +
             `started="${a.start}",raised_at="${a.at}",minutes_at_alert=${a.minutes},status="open" ${a.ts}`;
node.status({ fill: 'red', shape: 'dot', text: `${a.state} since ${a.start}` });
return [{ payload: line },
        { payload: `${a.state} for ${Math.round(dur / 60)} min since ${a.start} — ${a.reason}` },
        { payload: { open: a, list } }];

// The stop that raised the alert has ended -> close the SAME alert row (same tags + timestamp).
const s = msg.payload;
const a = flow.get('alert');
if (!a || a.since !== s.sinceS) return null;
const esc = t => String(t).replace(/[ ,=]/g, m => '\\' + m);
const done = { ...a, status: 'cleared', end: s.end, total: s.minutes };
flow.set('alert', false);                       // false, not null: null would delete the key
const list = (flow.get('alerts') || []).map(x => x.ts === a.ts ? done : x);
flow.set('alerts', list);
const line = `alerts,line=packaging,state=${a.state},reason=${esc(a.reason)} ` +
             `status="cleared",cleared_at="${s.end}",total_minutes=${s.minutes} ${a.ts}`;
node.status({ fill: 'green', shape: 'dot', text: `cleared ${s.end} · ${s.minutes} min` });
return [{ payload: line }, { payload: { open: null, list } }];

// Machine clock reached the end of the shift -> build the report once.
const p = msg.payload;
const END = (Number(env.get('SHIFT_HOURS')) || 8) * 3600;
if (flow.get('shiftStart') === undefined) return null;            // restore not finished yet
if (p.clockS < END || flow.get('reported')) return null;
flow.set('reported', true);
return { payload: { reason: 'end of shift' } };

// Ask InfluxDB about this shift: one query per part of the report
const base = env.get('INFLUX_URL') || 'http://127.0.0.1:8181';
const headers = { 'Authorization': 'Bearer ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'application/json' };
const start = flow.get('shiftStart') || (Date.now() - 8 * 3600e3);
const W = `time >= to_timestamp_millis(${start})`;
const q = (topic, sql) => ({ topic, method: 'POST', url: `${base}/api/v3/query_sql`, headers,
                             payload: { db: 'factory', q: sql, format: 'json' } });
flow.set('reportStart', start);
return [[
  q('oee', `SELECT
      SUM(CASE WHEN bucket = 'run'       THEN dt ELSE 0 END) / 60.0 AS run_min,
      SUM(CASE WHEN bucket = 'planned'   THEN dt ELSE 0 END) / 60.0 AS planned_min,
      SUM(CASE WHEN bucket = 'unplanned' THEN dt ELSE 0 END) / 60.0 AS unplanned_min,
      (MAX(good) - MIN(good)) * 1.0 AS good,
      (MAX(scrap) - MIN(scrap)) * 1.0 AS scrap
    FROM machine WHERE ${W}`),
  q('reasons', `SELECT CASE WHEN op_reason <> '' THEN op_reason
                     WHEN state = 'IDLE' THEN 'idle – waiting for operator' ELSE reason END AS reason,
                ROUND(SUM(minutes), 1) AS minutes, COUNT(*) AS n
    FROM stops WHERE type = 'unplanned' AND ${W} GROUP BY 1 ORDER BY minutes DESC LIMIT 3`),
  q('stops', `SELECT COUNT(*) AS n,
      SUM(CASE WHEN state = 'IDLE' THEN 1 ELSE 0 END) AS idle,
      SUM(CASE WHEN state = 'IDLE' AND op_reason <> '' THEN 1 ELSE 0 END) AS answered
    FROM stops WHERE type = 'unplanned' AND ${W}`),
  q('longest', `SELECT started, ended, minutes, state,
      CASE WHEN op_reason <> '' THEN op_reason ELSE reason END AS why
    FROM stops WHERE type = 'unplanned' AND ${W} ORDER BY minutes DESC LIMIT 1`),
  q('alerts', `SELECT COUNT(*) AS n FROM alerts WHERE ${W}`)
]];

// Collect the five answers -> one report object -> page, InfluxDB row, HTML file, toast
const got = context.get('got') || {};
got[msg.topic] = (msg.statusCode === 200 && Array.isArray(msg.payload)) ? msg.payload : [];
if (Object.keys(got).length < 5) { context.set('got', got); return null; }
context.set('got', {});
const o = got.oee[0] || {};
const run = Number(o.run_min) || 0, un = Number(o.unplanned_min) || 0, pl = Number(o.planned_min) || 0;
const good = Number(o.good) || 0, parts = good + (Number(o.scrap) || 0);
const A = run / (run + un), P = 2.0 * parts / (run * 60), Q = good / parts;   // ideal cycle 2.0 s
const st = got.stops[0] || {}, L = got.longest[0];
const pct = x => (100 * x).toFixed(1) + '%';
const R = {
  date: new Date().toISOString().slice(0, 10),
  oee: pct(A * P * Q), availability: pct(A), performance: pct(P), quality: pct(Q),
  run: run.toFixed(1), planned: pl.toFixed(1), unplanned: un.toFixed(1), good, scrap: parts - good,
  stops: Number(st.n) || 0, idle: Number(st.idle) || 0, answered: Number(st.answered) || 0,
  alerts: Number((got.alerts[0] || {}).n) || 0,
  top: got.reasons.map(r => ({ reason: r.reason, minutes: Number(r.minutes), n: Number(r.n) })),
  longest: L ? `${L.started}–${L.ended} · ${L.minutes} min · ${L.state} · ${L.why}` : '–'
};
const esc = t => String(t).replace(/"/g, "'");
const line = `shift_reports,line=packaging oee=${(A * P * Q).toFixed(4)},availability=${A.toFixed(4)},` +
  `performance=${P.toFixed(4)},quality=${Q.toFixed(4)},run_min=${R.run},planned_min=${R.planned},` +
  `unplanned_min=${R.unplanned},stops=${R.stops}i,idle_stops=${R.idle}i,idle_answered=${R.answered}i,` +
  `alerts=${R.alerts}i,top_reason="${esc(R.top[0] ? R.top[0].reason : '')}",longest="${esc(R.longest)}" ${Date.now()}`;
const rows = R.top.map((t, i) => `<tr><td>${i + 1}. ${t.reason}</td><td>${t.minutes} min</td><td>${t.n}×</td></tr>`).join('');
const html = `<!doctype html><html><head><meta charset="utf-8"><title>Shift report ${R.date}</title>
<style>body{font-family:Arial,sans-serif;max-width:720px;margin:32px auto;color:#1b1f24}h1{margin:0 0 4px}
.k{display:flex;gap:12px;margin:18px 0}.k div{flex:1;border:1px solid #ccc;border-radius:8px;padding:10px}
.k b{display:block;font-size:26px}table{border-collapse:collapse;width:100%}td{border-bottom:1px solid #ddd;padding:6px}</style>
</head><body><h1>Shift report – packaging line</h1><p>${R.date} · 8 h shift · generated by Node-RED</p>
<div class="k"><div>OEE<b>${R.oee}</b></div><div>Availability<b>${R.availability}</b></div>
<div>Performance<b>${R.performance}</b></div><div>Quality<b>${R.quality}</b></div></div>
<p>Running ${R.run} min · planned stops ${R.planned} min · unplanned stops ${R.unplanned} min · good ${R.good} / scrap ${R.scrap}</p>
<h3>Top unplanned reasons</h3><table>${rows}</table>
<p>Longest stop: ${R.longest}</p>
<p>${R.stops} unplanned stops · operator answered ${R.answered} of ${R.idle} idle stops · ${R.alerts} long-stop alert(s)</p></body></html>`;
const dir = env.get('REPORT_DIR') || 'reports';
node.status({ fill: 'green', shape: 'dot', text: `OEE ${R.oee} · ${R.alerts} alert(s)` });
return [{ payload: R }, { payload: line },
        { payload: html, filename: `${dir}/shift_report_${R.date}_${Date.now()}.html` },
        { payload: `Shift report ready: OEE ${R.oee}` }];
